import gzip
import json
import pathlib

import pytest

REPO = pathlib.Path(__file__).resolve().parents[2]

#: Generated by `node tools/gen_armv6m_tests.mjs`, git-ignored because it is
#: derived and large. Its absence is a skip, never a pass: the same contract
#: the rule checkers keep when they cannot find a PICSimLab source tree.
CORPUS = REPO / "third_party" / "armv6m" / "v1"

#: Where the generator puts the instruction under test and its scratch words,
#: and the SRAM they sit in. All three are the generator's constants rather
#: than this file's -- see gen_armv6m_tests.mjs, which uses rp2040js's
#: RAM_START_ADDRESS plus 0x1000 and 0x2000.
#:
#: The core has no memory of its own, so a test that wants any must say so.
#: These tests are about instructions rather than about a board, so they get
#: the plainest possible map: one flat SRAM, no peripherals, nothing else.
SRAM = 0x20000000
SRAM_SIZE = 264 * 1024
PC = 0x20001000
SANDBOX = 0x20002000


@pytest.fixture(scope="session")
def corpus_dir() -> pathlib.Path:
    if not CORPUS.is_dir() or not any(CORPUS.glob("*.json.gz")):
        pytest.skip(
            f"no Armv6-M corpus at {CORPUS}. Generate one:\n"
            "  git clone https://github.com/wokwi/rp2040js ../rp2040js\n"
            "  (cd ../rp2040js && npm install && npm run build)\n"
            "  node tools/gen_armv6m_tests.mjs --count 500"
        )
    return CORPUS


def load_family(directory: pathlib.Path, family: str) -> list[dict]:
    return json.loads(gzip.open(directory / f"{family}.json.gz").read())


@pytest.fixture(scope="session")
def cpu():
    """One core for the whole session.

    Reused rather than rebuilt per case because the corpus is thousands of
    cases and every one of them calls `clear_memory` and `set_regs` anyway --
    which is the whole of the state this core has.
    """
    abi = pytest.importorskip("core.cortexm0.abi")
    with abi.Cpu() as instance:
        yield instance


@pytest.fixture(autouse=True)
def _no_registers_leak_between_tests(cpu):
    """Un-install any board the previous test mapped.

    The `cpu` fixture is session-scoped so the 13,500-case corpus does not pay
    to construct one per case, and `clear_memory` deliberately does not touch
    the register map. Without this, installing an RP2040 in one test left its
    registers mapped in every test after it -- which is exactly how two tests
    asserting "this address is not mapped" started failing the moment a board
    existed.
    """
    cpu.clear_registers()
    cpu.clear_regions()
    # The core ships with no memory, so every test starts by declaring the
    # map it needs. Tests that want a whole board call `rp2040.install`, which
    # replaces this with the real one.
    cpu.add_region(SRAM, SRAM_SIZE)
    yield
